import json, numpy as np, re, os

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G_all = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G_all and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G_all[k] = [[int(x) for x in r] for r in rows]

test_input = G_all['Test input']
test_input_arr = np.array(test_input)

def apply_rule(grid_arr):
    result = grid_arr.copy()
    # Background is the first unique value (smallest integer, which appears most)
    bg_value = sorted(np.unique(result))[0]
    for r in range(result.shape[0]):
        if result[r, -1] == bg_value:
            if len(set(result[r])) > 1:
                result[r, -1] = 1
    return result

result = apply_rule(test_input_arr)
print(json.dumps(result.tolist()))

